C", "aliases": [], "prix_unitaire_ht": null, "unite": "forfait", "fiche_cee": "BAR-TH-168", "eligible_cee": true, "eligible_mpr": true, "caracteristiques": {"code_article": "3023376", "volume_l": 200.0, "appoint": "électrique", "capteurs_a_associer": true, "famille": "Pack ballon solaire (CESI)", "classe_energetique": "C", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "prix_a_renseigner": true, "fiche_cee": "BAR-TH-168", "aides_a_verifier": true}, "description": "Chaffoteaux · Pack ballon solaire (CESI) · 200 L · appoint électrique · capteurs à associer · classe C."}, {"nom": "Pack ballon solaire CESI Chaffoteaux Pack Ballon Easy 200 GAZ (3023301) : ballon Zelios Compact CD2 200 200 L, régulation Expert Control, 2 × 10 L de fluide caloporteur — capteurs à associer", "nom_brut": false, "marque": "Chaffoteaux", "reference": "CESI-CHAFF-ZELIOS-EASY-200-GAZ", "aliases": [], "prix_unitaire_ht": null, "unite": "forfait", "fiche_cee": "BAR-TH-168", "eligible_cee": true, "eligible_mpr": true, "caracteristiques": {"code_article": "3023301", "volume_l": 200.0, "appoint": "gaz", "capteurs_a_associer": true, "famille": "Pack ballon solaire (CESI)", "classe_energetique": "C", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "prix_a_renseigner": true, "fiche_cee": "BAR-TH-168", "aides_a_verifier": true}, "description": "Chaffoteaux · Pack ballon solaire (CESI) · 200 L · appoint gaz · capteurs à associer · classe C."}, {"nom": "Pack ballon solaire CESI Chaffoteaux Pack Ballon Easy 300 ELEC (3023377) : ballon Zelios Compact CDE 300 300 L, régulation Expert Control, 2 × 10 L de fluide caloporteur — capteurs à associer", "nom_brut": false, "marque": "Chaffoteaux", "reference": "CESI-CHAFF-ZELIOS-EASY-300-ELEC", "aliases": [], "prix_unitaire_ht": null, "unite": "forfait", "fiche_cee": "BAR-TH-168", "eligible_cee": true, "eligible_mpr": true, "caracteristiques": {"code_article": "3023377", "volume_l": 300.0, "appoint": "électrique", "capteurs_a_associer": true, "famille": "Pack ballon solaire (CESI)", "classe_energetique": "C", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "prix_a_renseigner": true, "fiche_cee": "BAR-TH-168", "aides_a_verifier": true}, "description": "Chaffoteaux · Pack ballon solaire (CESI) · 300 L · appoint électrique · capteurs à associer · classe C."}, {"nom": "Pack ballon solaire CESI Chaffoteaux Pack Ballon Easy 300 GAZ (3023302) : ballon Zelios Compact CD2 300 300 L, régulation Expert Control, 2 × 10 L de fluide caloporteur — capteurs à associer", "nom_brut": false, "marque": "Chaffoteaux", "reference": "CESI-CHAFF-ZELIOS-EASY-300-GAZ", "aliases": [], "prix_unitaire_ht": null, "unite": "forfait", "fiche_cee": "BAR-TH-168", "eligible_cee": true, "eligible_mpr": true, "caracteristiques": {"code_article": "3023302", "volume_l": 300.0, "appoint": "gaz", "capteurs_a_associer": true, "famille": "Pack ballon solaire (CESI)", "classe_energetique": "C", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "prix_a_renseigner": true, "fiche_cee": "BAR-TH-168", "aides_a_verifier": true}, "description": "Chaffoteaux · Pack ballon solaire (CESI) · 300 L · appoint gaz · capteurs à associer · classe C."}]$produits$::jsonb) LOOP
    v_aliases := ARRAY(SELECT jsonb_array_elements_text(p->'aliases'));

    SELECT id INTO v_id
    FROM public.catalogue_produits
    WHERE entreprise_id = v_entreprise
      AND (reference = p->>'reference' OR reference = ANY(v_aliases))
    ORDER BY (reference = p->>'reference') DESC, actif DESC, created_at NULLS LAST
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO public.catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description, caracteristiques,
        prix_unitaire_ht, unite, tva_taux, eligible_mpr, eligible_cee, fiche_cee, actif,
        public_cible, catalogue_groupe, forfait_pose_ht, forfait_evacuation_ht
      ) VALUES (
        v_entreprise, 'solaire_thermique', p->>'nom', COALESCE(p->>'marque', ''), p->>'reference',
        COALESCE(p->>'description', ''), COALESCE(p->'caracteristiques', '{}'::jsonb),
        COALESCE(NULLIF(p->>'prix_unitaire_ht', '')::numeric, 0),
        COALESCE(p->>'unite', 'unite'), 5.5,
        COALESCE((p->>'eligible_mpr')::boolean, false), COALESCE((p->>'eligible_cee')::boolean, false),
        COALESCE(p->>'fiche_cee', ''), true, 'particulier', 'particulier', 0, 0
      );
      v_ajoutes := v_ajoutes + 1;
    ELSE
      UPDATE public.catalogue_produits SET
        categorie = 'solaire_thermique',
        nom = CASE WHEN COALESCE((p->>'nom_brut')::boolean, false) THEN nom ELSE p->>'nom' END,
        marque = COALESCE(NULLIF(p->>'marque', ''), marque),
        reference = p->>'reference',
        description = CASE
          WHEN COALESCE(btrim(description), '') = ''
            OR description = nom
            OR description = p->>'nom'
          THEN p->>'description'
          ELSE description
        END,
        caracteristiques = (COALESCE(caracteristiques, '{}'::jsonb) - 'prix_a_renseigner'::text)
                           || ((p->'caracteristiques') - 'prix_a_renseigner'::text)
                           || CASE WHEN array_length(v_aliases, 1) > 0 AND reference = ANY(v_aliases)
                                THEN jsonb_build_object('ancienne_reference', reference)
                                ELSE '{}'::jsonb END,
        prix_unitaire_ht = COALESCE(NULLIF(p->>'prix_unitaire_ht', '')::numeric, prix_unitaire_ht),
        tva_taux = 5.5,
        eligible_mpr = COALESCE((p->>'eligible_mpr')::boolean, false),
        eligible_cee = COALESCE((p->>'eligible_cee')::boolean, false),
        fiche_cee = COALESCE(p->>'fiche_cee', ''),
        actif = true
      WHERE id = v_id;
      v_maj := v_maj + 1;
    END IF;

    -- Autres lignes portant l'ancienne référence (doublons probables) : laissées actives, à confirmer.
    IF array_length(v_aliases, 1) > 0 THEN
      SELECT v_doublons + count(*) INTO v_doublons
      FROM public.catalogue_produits
      WHERE entreprise_id = v_entreprise AND reference = ANY(v_aliases) AND id <> COALESCE(v_id, '00000000-0000-0000-0000-000000000000'::uuid);
    END IF;
    v_id := NULL;
  END LOOP;

  -- Drapeau « prix à renseigner » aligné sur le prix réellement présent.
  UPDATE public.catalogue_produits
  SET caracteristiques = CASE
